%Dimensions and Positions

%Define dimensions of a room

length =16; %[control:slider:668a]{"position":[9,11]}
width =19; %[control:slider:4b6b]{"position":[8,10]}
height =9; %[control:slider:61b8]{"position":[9,10]}

%Create room dimensions array

room = [length,width,height];

%Define receiver positions

rx = [1,6,1];

rx2 = [1,1,1];

%Define transmitter position

tx = [6,6,1];

%Impulse responses from transmitter to receiver

irTR = acousticRoomResponse(room,tx,rx);

irRT = acousticRoomResponse(room,rx,tx);

%Time vectors

t = linspace(0,0.2,size(irTR,2));

t2 = linspace(0,0.2,size(irRT,2));

%Plot impulse response of the room for first position

subplot(2,1,1) %[output:4912ac33]

plot(t, irTR); %[output:4912ac33]

%Labels

xlabel 'Time (s)' %[output:4912ac33]
ylabel 'Magnitude' %[output:4912ac33]

title 'Impulse Response - Transmitter -> Receiver' %[output:4912ac33]

%Plot impulse response of the room for the second position

subplot(2,1,2) %[output:4912ac33]

plot(t2, irRT); %[output:4912ac33]

%Labels

xlabel 'Time (s)' %[output:4912ac33]
ylabel 'Magnitude' %[output:4912ac33]

title 'Impulse Response - Receiver -> Transmitter' %[output:4912ac33]

 
%%
%Create signal

f = 1000; %[control:editfield:74a6]{"position":[5,9]}

y = (0.25*cos(2*pi*f*t) + 0.25*cos(4*pi*f*t) + 0.25*cos(8*pi*f*t) + 0.25*cos(16*pi*f*t)).*exp(-300*t); %[control:editfield:7b3e]{"position":[96,99]}

%Length of signal

N = 200; %[control:editfield:1198]{"position":[5,8]}

y(N:end) = 0;

%Plot generated signal

figure(2)

plot(t(1:N), y(1:N)); %[output:636cbfbb]

xlabel 'Time (s)' %[output:636cbfbb]
ylabel 'Magnitude' %[output:636cbfbb]

title 'Actuator Signal' %[output:636cbfbb]

%Send y signal down channel from tx to rx

y_rec = conv(irTR,y);

%Send the received signal (time reversed) back from rx to tx

y_time_reversed = fliplr(y_rec);

y_back = conv(irRT,y_time_reversed);

y_back = cat(2,y_back,y_back);

y_back = cat(2,y_back,y_back);

y_back = cat(2,y_back,y_back);

%Plot both of these signals to see what it is like

figure(3)

subplot(2,1,1) %[output:629b79ff]

t3 = linspace(0,0.2,size(y_rec,2));

plot(t3,y_rec); %[output:629b79ff]

xlabel 'Time (s)' %[output:629b79ff]
ylabel 'Magnitude' %[output:629b79ff]

title 'Signal at receiver' %[output:629b79ff]

subplot (2,1,2) %[output:629b79ff]

t4 = linspace(0,0.2,size(y_back,2));

plot(t4,y_back); %[output:629b79ff]

xlabel 'Time (s)' %[output:629b79ff]
ylabel 'Magnitude' %[output:629b79ff]

title 'Time reversed signal at Transmitter' %[output:629b79ff]


